function makePhone(id,live=false){const phone=document.createElement('div');phone.className=`phone v${id+1}`;phone.dataset.design=id;phone.dataset.palette=config.palette==='auto'?designs[id].palette:config.palette;phone.dataset.live=String(live);phone.innerHTML=`<div class="statusbar"><span>9:41</span><span>▴ ▥ ▰</span></div><div class="app-header"><button class="icon-button menu-button" aria-label="打开导航">${svg('menu')}</button><span>XSTAR / MUSIC SPACE</span><button class="icon-button appearance-button" aria-label="外观设置">${svg('appearance')}</button></div><div class="screen"></div><div class="dock"></div><div class="gesture"></div>`;phoneStates.set(phone,{page:'player'});phone.querySelector('.appearance-button').onclick=openSettings;phone.querySelector('.menu-button').onclick=()=>{setPage(phone,'settings')};renderScreen(phone);renderDock(phone);return phone}
