function animate(now){const dt=frameTime?Math.min((now-frameTime)/1000,.1):0;frameTime=now;if(document.hidden){requestAnimationFrame(animate);return}if(playing){musicTime+=dt;position=realAudio?audio.currentTime:(position+dt)%tracks[trackIndex].duration}const motion=$('#motion').checked&&!reduceMotion.matches;let energy=0;if(realAudio&&analyser){analyser.getByteFrequencyData(bins);analyser.getByteTimeDomainData(wave);energy=bins.slice(0,18).reduce((s,v)=>s+v,0)/(18*255)}else if(playing){const phase=(musicTime*tracks[trackIndex].bpm/60)%1;energy=.18+.65*Math.exp(-phase*7)+.12*Math.sin(musicTime*5)**2}smoothed+=(energy-smoothed)*.24;const beat=playing&&motion?smoothed:0,duration=realAudio&&Number.isFinite(audio.duration)?audio.duration:tracks[trackIndex].duration;
 for(const [phone,state] of phoneStates){if((mode==='gallery')===(phone.dataset.live==='true'))continue;const r=phone.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)continue;phone.style.setProperty('--beat',beat.toFixed(3));phone.style.setProperty('--progress',`${position/duration*100}%`);const canvas=phone.querySelector('.core canvas');if(canvas)drawMusic(canvas,Number(phone.dataset.design),beat,musicTime,playing&&motion&&canvas.closest('.nav-item').dataset.page==='player');if(now-lastUI>240){phone.querySelectorAll('.elapsed,.time-glyph').forEach(el=>el.textContent=time(position));const seek=phone.querySelector('.seek');if(seek&&document.activeElement!==seek)seek.value=position/duration*1000;const dur=phone.querySelector('.duration');if(dur)dur.textContent=time(duration);if(realAudio&&state.page==='player'){phone.querySelector('.track-title').textContent=$('#audioFile').files[0]?.name.replace(/\.[^.]+$/,'')||'本地音乐';phone.querySelector('.track-artist').textContent='LOCAL AUDIO · 实时频谱';phone.querySelector('.lyrics').innerHTML='本地音频正在播放<strong>让底栏跟随此刻的声音</strong>音频仅在当前浏览器读取'}}}if(now-lastUI>240)lastUI=now;requestAnimationFrame(animate)}
